import path from 'node:path'
import fs from 'node:fs'
import type { Plugin } from 'vite'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

const DATA_DIR = path.resolve(import.meta.dirname, '../data')
const MIME: Record<string, string> = {
  '.json': 'application/json',
  '.geojson': 'application/geo+json',
}

/**
 * Serves the project's ../data folder at /data (dev and `vite preview`): the data is generated by the
 * Python pipeline and must never be copied into web/. In production index.html sits next to data/.
 */
function serveProjectData(): Plugin {
  const handler = (req: any, res: any, next: () => void) => {
    const url = (req.url ?? '').split('?')[0]
    const m = /^(?:\/investment)?\/data\/([^/]+)$/.exec(url)
    if (!m) return next()
    const file = path.join(DATA_DIR, decodeURIComponent(m[1]))
    if (!file.startsWith(DATA_DIR) || !fs.existsSync(file) || !fs.statSync(file).isFile()) {
      res.statusCode = 404
      return res.end('not found')
    }
    const st = fs.statSync(file)
    const etag = `W/"${st.size}-${st.mtimeMs}"`
    if (req.headers['if-none-match'] === etag) {
      res.statusCode = 304
      return res.end()
    }
    res.setHeader('Content-Type', MIME[path.extname(file)] ?? 'application/octet-stream')
    res.setHeader('ETag', etag)
    res.setHeader('Cache-Control', 'no-cache')
    fs.createReadStream(file).pipe(res)
  }
  return {
    name: 'serve-project-data',
    configureServer(server) { server.middlewares.use(handler) },
    configurePreviewServer(server) { server.middlewares.use(handler) },
  }
}

export default defineConfig({
  base: './',
  plugins: [react(), tailwindcss(), serveProjectData()],
  resolve: { alias: { '@': path.resolve(import.meta.dirname, './src') } },
  worker: { format: 'es' },
  build: { target: 'es2022', chunkSizeWarningLimit: 900 },
  server: { port: 5173, fs: { allow: ['..'] } },
})
